// launch-factory: 웹 푸시 조립. 로그인한 사용자의 기기 구독을 저장하고 VAPID 로 알림을 보낸다(비로그인 방문자는 메일·알림톡).
// live 에서 VAPID_PUBLIC_KEY·VAPID_PRIVATE_KEY·VAPID_SUBJECT 가 모두 맞아야 켜진다 — 없거나 틀리면 이 기능만 꺼진다(pushEnabled() 가 false, 구독은 provider_unavailable).
// mock 은 외부 호출 0 이다: 구독은 저장하고 보내기는 기록만 한다. 키 생성: npx web-push generate-vapid-keys
import { createPushService, isValidVapid, type PushService } from "@launch-factory/push"
import { database } from "@/lib/launch/db"
import { env, optional } from "@/lib/launch/env"

function vapid() {
  return { subject: optional("VAPID_SUBJECT") ?? "", publicKey: optional("VAPID_PUBLIC_KEY") ?? "", privateKey: optional("VAPID_PRIVATE_KEY") ?? "" }
}

/** 구독·보내기가 되는가. 데이터베이스에 닿지 않는다 */
export function pushEnabled(): boolean {
  return env().LF_MODE !== "live" || isValidVapid(vapid())
}

let cached: Promise<PushService> | undefined

export function push(): Promise<PushService> {
  return (cached ??= build())
}

async function build(): Promise<PushService> {
  const live = env().LF_MODE === "live"
  const keys = vapid()
  return createPushService({
    db: await database(),
    mode: live ? "live" : "mock",
    ...(isValidVapid(keys) ? { vapid: keys } : {}),
    onError: (e) => console.error("[push]", e instanceof Error ? e.name : "error"),
  })
}

"use server"
// launch-factory: 웹 푸시 서버 액션 — 로그인한 사용자만. 공개 경로라 입력은 서비스가 먼저 검사한다(구독 모양·길이).
// 브라우저는 pushPublicKey() 로 받은 공개키로 pushManager.subscribe 한 뒤 그 결과(toJSON)를 subscribePush 에 넘긴다. 푸시를 보내는 쪽은 서버 코드가 push().sendToUser 를 부른다.
import { pushPortMethods } from "@launch-factory/push"
import type { ActionResult, IsoDate } from "@launch-factory/contract"
import { authPort } from "@/lib/launch/auth"
import { push, pushEnabled } from "@/lib/launch/push"

/** 로그인했으면 사용자 id. 로그아웃·만료·대리 로그인 세션은 null(대리 세션이 그 사람 기기를 등록하지 못한다) */
async function userId(): Promise<string | null> {
  try {
    const s = await (await authPort()).session()
    return s.ok && s.data && !s.data.impersonatedBy ? s.data.userId : null
  } catch {
    return null
  }
}

/** 구독에 쓰는 공개키. 기능이 꺼져 있으면 null — 화면은 푸시 단추를 그리지 않는다 */
export async function pushPublicKey(): Promise<string | null> {
  return pushEnabled() ? (await push()).publicKey() : null
}

// 로그인 확인(userId)은 액션이 직접 부른다 — 포트에는 읽은 값만 넘긴다(가드가 이 파일에서 보이도록)
export async function subscribePush(input: unknown): Promise<ActionResult<{ subscribedAt: IsoDate }>> {
  const uid = await userId()
  return pushPortMethods(await push(), () => uid).subscribePush(input as never)
}

export async function unsubscribePush(input: unknown): Promise<ActionResult<Record<string, never>>> {
  const uid = await userId()
  return pushPortMethods(await push(), () => uid).unsubscribePush(input as never)
}

// launch-factory: 웹 푸시 서비스 워커. 서버가 보낸 JSON { title, body?, url?, tag?, icon? } 를 알림으로 띄우고, 누르면 이 사이트 안의 쪽을 연다.
// 같은 출처 경로(/…)가 아니면 열지 않고 홈으로 간다 — 알림 내용이 밖으로 보내는 길이 되지 않게.
self.addEventListener("install", () => self.skipWaiting())
self.addEventListener("activate", (event) => event.waitUntil(self.clients.claim()))

function readPayload(event) {
  try {
    return event.data ? event.data.json() || {} : {}
  } catch {
    return {}
  }
}

self.addEventListener("push", (event) => {
  const data = readPayload(event)
  const title = typeof data.title === "string" && data.title ? data.title : "알림"
  const options = {
    ...(typeof data.body === "string" ? { body: data.body } : {}),
    ...(typeof data.tag === "string" ? { tag: data.tag } : {}),
    ...(typeof data.icon === "string" && /^\/[^/\\]/.test(data.icon) ? { icon: data.icon } : {}),
    data: { url: typeof data.url === "string" ? data.url : "/" },
  }
  event.waitUntil(self.registration.showNotification(title, options))
})

self.addEventListener("notificationclick", (event) => {
  event.notification.close()
  const raw = event.notification.data && event.notification.data.url
  const path = typeof raw === "string" && /^\/[^/\\]/.test(raw) ? raw : "/"
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((windows) => {
      for (const w of windows) {
        if (new URL(w.url).pathname === path.split(/[?#]/)[0] && "focus" in w) return w.focus()
      }
      return self.clients.openWindow(path)
    }),
  )
})

// launch-factory: DB 연결. mock 은 메모리 PGlite(키 없이 켜진다), live 는 DATABASE_URL(Supabase 풀러 6543 — prepared statement 끔은 패키지가 한다).
// mock 의 마이그레이션은 이 앱에 설치된 db/migrations 를 쓴다(번들 안에서는 패키지 폴더를 찾을 수 없다).
import { join } from "node:path"
import { db, type Database } from "@launch-factory/db"
import { env, required } from "@/lib/launch/env"

let cached: Promise<Database> | undefined

/**
 * mock 의 메모리 DB 는 프로세스 하나에 하나다. 서버 번들은 쪽·서버 액션·경로 처리기(app/api)로 갈라져 같은 모듈이 번들마다 따로 불리므로(Next/Turbopack),
 * 모듈 변수에만 두면 번들 수만큼 DB 가 생겨 경로 처리기(웹훅·크론·/api/auth)와 쪽이 서로 다른 데이터를 보았다(관리 화면 시험 실측: 경로로 만든 세션이 쪽에서 안 보였다).
 * 그래서 globalThis 에 둔다. live 는 연결 문자열이 같은 DB 를 가리키므로 모듈 변수로 충분하다.
 */
const mockStore = globalThis as { __lfMockDb?: Promise<Database> }

export function database(): Promise<Database> {
  if (env().LF_MODE === "mock") return (mockStore.__lfMockDb ??= db.local({ migrationsFolder: join(process.cwd(), "db", "migrations") }))
  return (cached ??= Promise.resolve(db(required("DATABASE_URL"))))
}

// launch-factory: 환경 읽기. 이름만 다루고 값은 어디에도 남기지 않는다.
// LF_MODE 는 항상 필수다 — 없으면 켜지지 않는다(조용히 mock 으로 가지 않는다). live 에서는 공급자 키가 모두 필수다.
import { loadAppEnv, type AppEnv } from "@launch-factory/env"

let cached: AppEnv | undefined

/** 처음 부를 때 한 번 검사한다. 빠진 이름은 모두 모아 한 번에 알린다(값은 싣지 않는다). */
export function env(): AppEnv {
  return (cached ??= loadAppEnv())
}

/** 설정값·비밀값 하나를 읽는다. 없으면 이름만 담아 던진다. */
export function required(name: string): string {
  const value = (env() as Record<string, string | undefined>)[name] ?? process.env[name]
  if (!value) throw new Error(`${name} is not set (see .env.example)`)
  return value
}

/** 없어도 되는 설정값. */
export function optional(name: string): string | undefined {
  return process.env[name] || undefined
}

// launch-factory: 제품마다 고치는 값. 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
import type { Locale } from "@launch-factory/email"
import { env, required } from "@/lib/launch/env"

export const PRODUCT_NAME = "My Product"
/** 사용자 칸(user.locale)이 비었을 때 메일·오류 문구의 언어 */
export const DEFAULT_LOCALE: Locale = "en"
/** 가입 때 동의 기록에 남길 약관·개인정보 처리방침의 판. 문서를 고치면 올린다 */
export const CONSENT_VERSIONS = { terms: "2026-09-30", privacy: "2026-09-30" }
/** 결제 메일이 가리키는 화면 경로 */
export const ROUTES = { billing: "/account/billing", acceptPriceChange: "/account/billing/price-change", decline: "/account/billing/cancel", security: "/forgot-password", contact: "/contact" }

/** 앱 주소. mock 에서는 로컬 주소로 켜지고, live 에서는 NEXT_PUBLIC_APP_URL 이 필수다 */
export function appUrl(): string {
  // 빈 문자열은 없는 것으로 본다 — shadcn CLI 가 envVars 이름을 `NAME=`(빈 값)으로 .env.local 에 적는다
  return process.env.NEXT_PUBLIC_APP_URL || (env().LF_MODE === "mock" ? "http://localhost:3000" : required("NEXT_PUBLIC_APP_URL"))
}

// launch-factory: 마이그레이션 적용. 사용법: DATABASE_URL=<직접 연결(5432)> node db/migrate.mjs
// 이 폴더의 migrations/ 를 순서대로 적용한다. 이미 적용한 파일은 건너뛴다(drizzle 기록 표).
import { fileURLToPath } from "node:url"
import postgres from "postgres"
import { drizzle } from "drizzle-orm/postgres-js"
import { migrate } from "drizzle-orm/postgres-js/migrator"

const url = process.env.DATABASE_URL
if (!url) {
  console.error("DATABASE_URL is not set")
  process.exit(1)
}
if (new URL(url).port === "6543") {
  console.error("Use the direct connection (port 5432) for migrations, not the transaction pooler (6543).")
  process.exit(1)
}

const client = postgres(url, { max: 1 })
try {
  await migrate(drizzle(client), { migrationsFolder: fileURLToPath(new URL("./migrations", import.meta.url)) })
  console.log("migrations applied")
} finally {
  await client.end()
}

// 웹 푸시 구독(계획 3b, 설계서 9.5 — `push` 부품). 한 행 = 브라우저 기기 하나의 PushSubscription.
// - endpoint 는 푸시 서비스가 정한 기기별 주소라 유일하다. 같은 기기를 다른 사용자가 등록하면 소유자를 옮긴다(upsert).
// - 사용자를 지우면 구독도 지운다(cascade) — 알릴 사람이 없다.
// - failure_count: 연속 실패 횟수. 404/410 은 바로 지우고, 그 밖의 실패는 이 값이 한도를 넘으면 지운다(@launch-factory/push).
import { index, integer, bigint, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core"
import { user } from "./auth-base.ts"

const tz = { withTimezone: true } as const

export const pushSubscriptions = pgTable(
  "push_subscriptions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    endpoint: text("endpoint").notNull().unique(),
    p256dh: text("p256dh").notNull(),
    auth: text("auth").notNull(),
    expirationTime: bigint("expiration_time", { mode: "number" }),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    createdAt: timestamp("created_at", tz).notNull(),
    lastSuccessAt: timestamp("last_success_at", tz),
    failureCount: integer("failure_count").notNull().default(0),
  },
  (t) => [index("push_subscriptions_user_idx").on(t.userId)],
)

-- 접속기록 위·변조 방지(「개인정보의 안전성 확보조치 기준」 제8조제3항). access_logs는 추가 전용이다.
--   UPDATE·TRUNCATE: 항상 거부
--   DELETE: 접속일시가 1년(제8조제1항 최소 보관 기간)을 넘은 행만 허용 — 파기 작업이 2년 설정이면 그보다 늦게 지운다
-- 트리거는 역할과 상관없이 걸린다(표 소유자가 트리거를 끄는 것까지는 막지 못한다 — 해시 사슬은 다음 단계, docs/qa/task-3-report.md).
CREATE FUNCTION "access_logs_append_only"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP IN ('UPDATE', 'TRUNCATE') THEN
    RAISE EXCEPTION 'access_logs is append-only: % refused', TG_OP;
  END IF;
  IF OLD.occurred_at > now() - interval '1 year' THEN
    RAISE EXCEPTION 'access_logs: rows younger than 1 year cannot be deleted';
  END IF;
  RETURN OLD;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "access_logs_no_update_delete" BEFORE UPDATE OR DELETE ON "access_logs" FOR EACH ROW EXECUTE FUNCTION "access_logs_append_only"();
--> statement-breakpoint
CREATE TRIGGER "access_logs_no_truncate" BEFORE TRUNCATE ON "access_logs" FOR EACH STATEMENT EXECUTE FUNCTION "access_logs_append_only"();

-- 증빙 기록 보호(v0 Task 14, 대장 D66③).
-- consent_records: 동의 이력은 고치지 않는다(UPDATE·TRUNCATE 거부). DELETE 는 허용한다 — 탈퇴 파기(개인정보 보호법 제21조제1항)가 지운다.
--   청약철회 제한 동의(withdrawal_limit)는 파기 전에 retained_transactions 로 옮긴다(전자상거래법 시행령 제6조제1항제2호).
-- retained_transactions: 보존 거래기록은 고치지 않는다(UPDATE·TRUNCATE 거부). DELETE 는 retain_until 이 지난 행만 허용한다 —
--   법정 기간(시행령 제6조제1항)이 끝나기 전에 지우지 못하게 한다.
-- 트리거는 역할과 상관없이 걸린다(표 소유자가 트리거를 끄는 것은 막지 못한다 — access_logs 와 같은 한계, task-3 보고).
CREATE FUNCTION "consent_records_no_update"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'consent_records is append-only: % refused', TG_OP;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "consent_records_no_update" BEFORE UPDATE ON "consent_records" FOR EACH ROW EXECUTE FUNCTION "consent_records_no_update"();
--> statement-breakpoint
CREATE TRIGGER "consent_records_no_truncate" BEFORE TRUNCATE ON "consent_records" FOR EACH STATEMENT EXECUTE FUNCTION "consent_records_no_update"();
--> statement-breakpoint
CREATE FUNCTION "retained_transactions_guard"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP IN ('UPDATE', 'TRUNCATE') THEN
    RAISE EXCEPTION 'retained_transactions is append-only: % refused', TG_OP;
  END IF;
  IF OLD.retain_until > now() THEN
    RAISE EXCEPTION 'retained_transactions: rows cannot be deleted before retain_until';
  END IF;
  RETURN OLD;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "retained_transactions_no_update_delete" BEFORE UPDATE OR DELETE ON "retained_transactions" FOR EACH ROW EXECUTE FUNCTION "retained_transactions_guard"();
--> statement-breakpoint
CREATE TRIGGER "retained_transactions_no_truncate" BEFORE TRUNCATE ON "retained_transactions" FOR EACH STATEMENT EXECUTE FUNCTION "retained_transactions_guard"();

